function archiveHabit(id){const h=habitById(id);if(!h)return;h.archivedAt=nowStamp();h.status='Archived';h.updatedAt=nowStamp();save();closeModal();toast('Habit archived','decision_archived');render()}
function setQuietArea(area){const until=addDays(todayISO(),30);state.quietAreas[area]=until;save();toast(`${area} quiet until ${fmtDate(until)}`,'realm_renew');render()}
function calendarToTask(id){const e=state.calendarEvents.find(x=>x.id===id);if(!e)return;openTaskEditor(null,{title:`Prepare / follow up: ${e.title}`,area:e.area,plannedDate:e.date,startTime:e.startTime,endTime:e.endTime,standaloneType:'Resolve'})}
function shiftTaskOrder(taskId,targetId){const a=taskById(taskId),b=taskById(targetId);if(!a||!b||a.plannedDate!==b.plannedDate)return;const x=a.plannedOrder;a.plannedOrder=b.plannedOrder;b.plannedOrder=x;a.updatedAt=b.updatedAt=nowStamp();save();render()}
