function setMatrixTask(taskId,importance,urgency){const t=taskById(taskId);if(!t)return;t.importance=importance;t.urgency=urgency;t.updatedAt=nowStamp();save();toast(`Moved to ${priorityState(t)[0]}`,'priority_plan');render()}
function setNextMove(questId,taskId){const q=questById(questId);if(!q)return;q.nextMoveTaskId=taskId;q.updatedAt=nowStamp();save();closeModal();toast('Quest Next Move selected','goal_next');render()}
function resolveQuestion(questId,entryId){const q=questById(questId),e=q?.exploration.entries.find(x=>x.id===entryId);if(!e)return;e.resolved=true;e.updatedAt=nowStamp();q.updatedAt=nowStamp();save();toast('Question marked answered','decision_reached');render()}
function enableTrack(id,track){const q=questById(id);if(!q)return;if(track==='outcome')q.outcome.enabled=true;else q.exploration.enabled=true;q.updatedAt=nowStamp();save();openQuestEditor(q)}
function unscheduleTask(id){const t=taskById(id);if(!t)return;if(t.plannedDate)t.plannedDateHistory=[...(t.plannedDateHistory||[]),{from:t.plannedDate,to:null,at:nowStamp(),reason:'Returned to Unscheduled'}];t.plannedDate=null;t.updatedAt=nowStamp();save();closeModal();toast('Task returned to Unscheduled','clock_current');render()}
function restore(kind,id){const item=kind==='quest'?questById(id):habitById(id);if(!item)return;item.archivedAt=null;if(kind==='habit')item.status='Active';item.updatedAt=nowStamp();save();toast(`${kind==='quest'?'Quest':'Habit'} restored`,'clock_recovered');render()}

function handleSearchOpen(token){const [type,id]=token.split(':');closeModal();if(type==='task'){const t=taskById(id);if(t?.questId){state.ui.returnContext={view:'tasks'};state.ui.selectedQuestId=t.questId;state.ui.questTab='tasks';state.ui.questTaskFilter=t.track==='exploration'?'Exploration':'Goal/Project';save();setView('questbook',{keepQuest:true})}else openTaskEditor(t)}else if(type==='quest'){state.ui.selectedQuestId=id;state.ui.questTab='overview';save();setView('questbook',{keepQuest:true})}else if(type==='habit'){state.ui.questbookTab='habits';save();setView('questbook');setTimeout(()=>openHabitEditor(habitById(id)),30)}else{const n=state.notes.find(x=>x.id===id);if(n?.questId){state.ui.selectedQuestId=n.questId;state.ui.questTab='explore';save();setView('questbook',{keepQuest:true})}else setView('notes')}}


