function v33MoveCount(t){return Array.isArray(t?.plannedDateHistory)?t.plannedDateHistory.filter(x=>x.from!==x.to).length:0}
function v33PriorityRank(t){return V33_PRIORITY_RANK[`${t?.importance||'Medium'}-${t?.urgency||'Medium'}`]||99}
function v33PriorityShort(t){return `I${IMPORTANCE.indexOf(t?.importance)+1||2} · U${URGENCY.indexOf(t?.urgency)+1||2}`}
function v33OccurrenceClosed(o){return !!(o?.completedAt||o?.skippedAt)}
