function ensureHabitPeriods(){activeHabits().forEach(h=>v33EnsureUpcomingHabitOccurrences(h,3))}
function habitOccurrenceActivities(date){const out=[];activeHabits().forEach(h=>{v33EnsureUpcomingHabitOccurrences(h,3);(h.occurrences||[]).filter(o=>o.date===date).forEach(o=>out.push({key:`habit:${h.id}:${o.id}`,kind:'habit',date,habit:h,occurrence:o,category:'Habit',area:h.area,questId:h.questId,title:h.title,estimateMinutes:h.estimateMinutes||0,startTime:null,dueDate:periodBounds(h,date).end,topPriority:state.topPriorityByDate[date]===`habit:${h.id}:${o.id}`}))});return out}
function calendarActivities(date){const hidden=new Set(state.hiddenCalendarEventIds||[]);return state.calendarEvents.filter(e=>e.date===date&&!hidden.has(e.id)).map(e=>({key:`calendar:${e.id}`,kind:'calendar',date,calendar:e,category:'Calendar',area:e.area,title:e.title,estimateMinutes:0,startTime:e.startTime,dueDate:null,topPriority:false}))}
