function v33OpenTodaySort(){showModal(`${modalHeader('Sort within each date','The Planned / Due toggle controls grouping. Sort only changes the order inside each group.')}<div class="modal-body"><div class="choice-list">${[['manual','Manual order'],['priority','Priority sequence'],['quest','Project / Exploration'],['recent','Recently updated']].map(([v,l])=>`<button class="choice-row ${state.ui.todaySort===v?'active':''}" data-set-today-sort="${v}"><strong>${l}</strong><small>${v==='priority'?'3/3, 3/2, 2/3, 2/2, then lower combinations.':'Select this order.'}</small></button>`).join('')}</div></div>${modalActions('<button class="button ghost" data-close-modal>Close</button>','')}`)}

