document.addEventListener('click',e=>{
  const sort=e.target.closest('[data-open-today-sort]');if(sort){e.preventDefault();e.stopImmediatePropagation();v33OpenTodaySort();return}
  const setSort=e.target.closest('[data-set-today-sort]');if(setSort){e.preventDefault();e.stopImmediatePropagation();state.ui.todaySort=setSort.dataset.setTodaySort;save();closeModal();render();return}
  const starred=e.target.closest('[data-toggle-starred]');if(starred){e.preventDefault();e.stopImmediatePropagation();state.ui.starredOnly=!state.ui.starredOnly;save();render();return}
  const skip=e.target.closest('[data-skip-habit]');if(skip){e.preventDefault();e.stopImmediatePropagation();v33SkipHabit(skip.dataset.skipHabit,skip.dataset.occurrence);return}
  const hs=e.target.closest('[data-open-habit-schedule]');if(hs){e.preventDefault();e.stopImmediatePropagation();v33OpenHabitSchedule(hs.dataset.openHabitSchedule);return}
  const hide=e.target.closest('[data-hide-calendar]');if(hide){e.preventDefault();e.stopImmediatePropagation();v33HideCalendar(hide.dataset.hideCalendar);return}
  const restore=e.target.closest('[data-restore-calendar]');if(restore){e.preventDefault();e.stopImmediatePropagation();state.hiddenCalendarEventIds=state.hiddenCalendarEventIds.filter(x=>x!==restore.dataset.restoreCalendar);save();toast('Calendar event restored','object_event');render();return}
  const addStep=e.target.closest('[data-add-checklist-step]');if(addStep){e.preventDefault();e.stopImmediatePropagation();const input=$('#new-checklist-step'),title=String(input?.value||'').trim();if(!title)return;$('#task-checklist-editor')?.insertAdjacentHTML('beforeend',`<div class="checklist-edit-row" data-step-id="${uid('step')}"><input class="checklist-done" type="checkbox" aria-label="Step complete"><input class="checklist-title" value="${esc(title)}"><button type="button" data-remove-checklist-step aria-label="Remove step">×</button></div>`);input.value='';input.focus();return}
  const removeStep=e.target.closest('[data-remove-checklist-step]');if(removeStep){e.preventDefault();e.stopImmediatePropagation();removeStep.closest('.checklist-edit-row')?.remove();return}
},true);
