  const legacyType=String(q.questType||q.type||'').toLowerCase(),outcomeEnabled=q.outcome?.enabled??(['outcome','achieve','hybrid'].includes(legacyType)),explorationEnabled=q.exploration?.enabled??(['evolving','explore','hybrid'].includes(legacyType)),status=QUEST_STATUSES.includes(q.status)?q.status:(q.status==='Released'?'Stopped':q.status==='Capturing'?'To Start':['Shaping','Testing','Acting','Reviewing'].includes(q.status)?'In Progress':'To Start'),legacyEntries=Array.isArray(q.entries)?q.entries:[],rawStreams=Array.isArray(q.workstreams)?q.workstreams:(Array.isArray(q.sections)?q.sections:[]),rawEntries=Array.isArray(q.exploration?.entries)?q.exploration.entries:legacyEntries;
