    outcome:{enabled:!!outcomeEnabled,statement:q.outcome?.statement||q.successMeasure||((legacyType==='outcome'||legacyType==='achieve')?q.currentDirection||'':''),successCriteria:q.outcome?.successCriteria||q.successMeasure||'',targetDate:q.outcome?.targetDate||q.targetDate||null,progress:Number(q.outcome?.progress??q.progress??0),milestones:Array.isArray(q.outcome?.milestones)?q.outcome.milestones:(Array.isArray(q.milestones)?q.milestones:[])},
