  if(activity.kind==='calendar')control='<span class="activity-check calendar-check">◷</span>';
  else if(activity.kind==='habit'){const p=periodProgress(activity.habit,activity.date),quantity=activity.habit.measurement==='quantity';control=`<button class="activity-check habit ${closed?'checked':''} ${skipped?'skipped':''}" ${quantity?`data-update-habit="${activity.habit.id}"`:`data-complete-habit="${activity.habit.id}" data-occurrence="${activity.occurrence.id}"`} aria-label="${quantity?'Update habit quantity':closed?'Undo habit result':'Complete habit occurrence'}">${skipped?'—':activity.occurrence?.completedAt?'✓':`${p.actual}/${p.target}`}</button>`}
  else control=`<button class="activity-check ${closed?'checked':progress>0?'progress':''}" style="--progress:${progress}%" data-complete-task="${activity.task.id}" aria-label="${closed?'Mark incomplete':'Mark complete'}">${closed?'✓':progress>0?`${progress}%`:''}</button>`;
