  const dueSoon=take(openTasks().filter(t=>!t.plannedDate&&t.dueDate&&t.dueDate<=horizonEnd));
  const project=take(openTasks().filter(t=>t.questId&&t.track!=='exploration'&&!t.plannedDate));
  const exploration=take(openTasks().filter(t=>t.questId&&t.track==='exploration'&&!t.plannedDate));
  const resolve=take(openTasks().filter(t=>taskCategory(t)==='Resolve'&&!t.plannedDate));
  const renew=take(openTasks().filter(t=>taskCategory(t)==='Renew/Fun'&&!t.plannedDate));
  const habits=activeHabits().filter(h=>!periodProgress(h,targetDate).met),total=attention.length+dueSoon.length+project.length+exploration.length+resolve.length+renew.length+habits.length;
