function v34TaskLifecycleMenu(id){const t=taskById(id);if(!t)return;showModal(`${modalHeader('Task actions',t.title)}<div class="modal-body action-menu-list"><button data-v34-toggle-task-complete="${t.id}"><span>${isTaskComplete(t)?'Reopen task':'Mark complete'}</span><b>›</b></button><button data-v34-duplicate-task="${t.id}"><span>Duplicate task</span><b>›</b></button><button data-v34-archive-task="${t.id}"><span>Remove from active lists</span><small>Keeps the task and its history.</small></button><button class="destructive" data-v34-delete-task="${t.id}"><span>Move to Trash</span><b>›</b></button></div><footer class="modal-actions compact-footer"><div></div><div><button class="button ghost" data-close-modal>Close</button></div></footer>`)}
